/*

 */

CREATE TABLE "QUALITY_CONC"."ADIANTAMENTO_SOLICITACAO" (
    "IDADIANTAMENTO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IDEMPRESA" INTEGER NOT NULL,
    "NUCNPJEMPRESA" NVARCHAR(18) NOT NULL,
    "CNPJFATURAMENTO" NVARCHAR(18) NOT NULL,
    "VRSOLICITADO" DECIMAL(18,2) NOT NULL,
    "DESCRICAO" NVARCHAR(2000) NOT NULL,
    "ANEXOORCAMENTO" NVARCHAR(500),
    "ANEXONOTAFISCAL" NVARCHAR(500),
    "STATUS" NVARCHAR(30) NOT NULL DEFAULT 'EM ANDAMENTO',
    "DSJUSTIFICATIVA" NVARCHAR(2000),
    "IDUSUARIOCRIACAO" INTEGER NOT NULL,
    "DATACRIACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IDUSUARIOALTERACAO" INTEGER,
    "DATAALTERACAO" TIMESTAMP,
    "DATAFINALIZACAO" TIMESTAMP,
    "STATIVO" NVARCHAR(5) NOT NULL DEFAULT 'True'
    "RAZAOSOCIALFATURAMENTO" NVARCHAR(100) NOT NULL
    "DEPARTAMENTO" NVARCHAR(100) NOT NULL,
    "POSSUINOTAFISCAL" NVARCHAR(10) NOT NULL,
);


CREATE TABLE "QUALITY_CONC"."ADIANTAMENTO_PAGAMENTO" (
    "IDPAGAMENTO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IDADIANTAMENTO" INTEGER NOT NULL,
    "VLPAGAMENTO" DECIMAL(18,2) NOT NULL,
    "DATAPAGAMENTO" DATE,
    "FORMAPAGAMENTO" NVARCHAR(50),
    "NUPAGAMENTO" NVARCHAR(100),
    "ANEXOCOMPROVANTE" NVARCHAR(500),
    "DSOBSERVACAO" NVARCHAR(1000),
    "IDUSUARIOCRIACAO" INTEGER NOT NULL,
    "DATACRIACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "STATIVO" NVARCHAR(5) NOT NULL DEFAULT 'True'
);

CREATE TABLE "QUALITY_CONC"."ADIANTAMENTO_HISTORICO" (
    "IDHISTORICO" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "IDADIANTAMENTO" INTEGER NOT NULL,
    "STATUSANTERIOR" NVARCHAR(30),
    "STATUSNOVO" NVARCHAR(30),
    "ACAO" NVARCHAR(50) NOT NULL,
    "DSOBSERVACAO" NVARCHAR(2000),
    "IDUSUARIO" INTEGER NOT NULL,
    "DATAACAO" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

/* 
PRECISA SER CRIADA UMA PROMOÇÃO PARA O CLUBE

*/
CREATE TABLE "QUALITY_CONC_HML"."PROMOCAOPRODUTOCLUBEPRECO" (
    "IDPROMOCAO" INTEGER BY DEFAULT AS IDENTITY PRIMARY KEY
    "IDPRODUTO" NVARCHAR(200) NOT NULL
    "PRECO_VENDA" DECIMAL(20, 2) NOT NULL,
    "IDEMPRESA" INTEGER NOT NULL
    "IDGRUPOEMPRESARIAL" INTEGER NOT NULL,
    "DSPROMOCAO" NVARCHAR(200) NOT NULL,
    "DTHORAINICIOVIGENCIA" TIMESTAMP,
    "DTHORAFIMVIGENCIA" TIMESTAMP,
    "DTULTIMAATUALIZACAO" TIMESTAMP,
    "STATIVO" NVARCHAR(10) NOT NULL,
)

